/*
 * config_frames_test -- the whole machine held to MAME, with no ROM: the baked
 * CONFIG client boots on the no-BIOS stand-in with a generated character set,
 * link down, and its frames must hash as MAME's did for the same set-up
 * (config_golden.h, generated by tools/ab/config_golden.py from a MAME run).
 * CONFIG draws its text from the 8244 with a counter-interrupt per text row
 * and rewrites the objects mid-frame, so a match covers the 8048 and its
 * interrupts, the lazy raster renderer, the stand-in's readkey path and the
 * cartridge's APPBANK serving, all at once.
 *
 * Copyright (C) 2026 Thomas Cherryhomes
 * SPDX-License-Identifier: GPL-3.0-or-later
 */

#include <stdio.h>
#include <string.h>

#include "o2_internal.h"
#include "config_golden.h"

/* the generated test font: tools/ab/o2ab.py test_font() */
static void make_font(uint8_t font[512])
{
    for (uint32_t i = 0; i < 512; i++)
        font[i] = (uint8_t)((i * 2654435761u) >> 24);
}

static unsigned long long fnv64(const uint32_t *px, size_t n)
{
    unsigned long long h = 14695981039346656037ull;

    for (size_t i = 0; i < n; i++) {
        h ^= px[i] & 0xffffffu;
        h *= 1099511628211ull;
    }
    return h;
}

int main(void)
{
    static o2_machine_t m;
    uint8_t font[512];
    o2_machine_opts_t mo;
    o2_fujinet_t *fj;
    char why[160];
    int failures = 0, next = 0, last = 0;
    const int n = (int)(sizeof k_config_golden / sizeof k_config_golden[0]);

    for (int i = 0; i < n; i++)
        if (k_config_golden[i].frame > last)
            last = k_config_golden[i].frame;
    make_font(font);
    fj = o2_fujinet_create();
    if (!fj || o2_fujinet_power_on(fj, NULL, 0, "", true, why, sizeof why) != 0) {
        fprintf(stderr, "config_frames: cannot power on the cartridge: %s\n", why);
        return 1;
    }
    memset(&mo, 0, sizeof mo);
    mo.machine = O2_MACHINE_ODYSSEY2;
    mo.font = font;
    mo.cart = o2_fujinet_cart(fj);
    mo.fujinet = fj;
    o2_machine_init(&m, &mo);

    for (int f = 0; f <= last; f++) {
        o2_machine_run_frame(&m);
        while (next < n && k_config_golden[next].frame == f) {
            unsigned long long h = fnv64(m.fb, O2_FB_WIDTH * O2_FB_HEIGHT);

            if (h == k_config_golden[next].hash) {
                printf("ok: frame %d matches MAME (%016llx)\n", f, h);
            } else {
                printf("FAIL: frame %d is %016llx, MAME's is %016llx\n", f, h,
                       k_config_golden[next].hash);
                failures++;
            }
            next++;
        }
    }
    o2_fujinet_destroy(fj);
    printf("%d failure(s)\n", failures);
    return failures ? 1 : 0;
}
